class MinStack:
    def __init__(self):
        self.data = []
        self.mins = []

    def push(self, x):
        self.data.append(x)
        if not self.mins or x <= self.mins[-1]:
            self.mins.append(x)
        print("push", x, "-> stack:", self.data, "min:", self.mins[-1])

    def pop(self):
        x = self.data.pop()
        if x == self.mins[-1]:
            self.mins.pop()
        print("pop", x, "-> stack:", self.data, "min:", self.mins[-1])
        return x

