import re

TAG = re.compile(r"<(/?)([a-zA-Z0-9]+)(/?)>")

def check(html):
    stack = []
    for m in TAG.finditer(html):
        closing, name, selfclose = m.group(1), m.group(2), m.group(3)
        if selfclose:
            continue
        if closing:
            if not stack:
                return "FAIL: closing </%s> with empty stack" % name
            if stack[-1] != name:
                return "FAIL: closing </%s> but innermost open tag is <%s>" % (name, stack[-1])
            stack.pop()
        else:
            stack.append(name)
    if stack:
        return "FAIL: unclosed tags left: %s" % stack
    return "OK"

