from collections import deque

def sliding_max(arr, k):
    dq = deque()  # indices, values decreasing front to back
    out = []
    for i, x in enumerate(arr):
        while dq and arr[dq[-1]] <= x:
            dq.pop()
        dq.append(i)
        if dq[0] <= i - k:
            dq.popleft()
        if i >= k - 1:
            out.append(arr[dq[0]])
            print("window", arr[i - k + 1:i + 1], "-> max", arr[dq[0]], "| deque indices:", list(dq))
    return out

