class TwoStackQueue:
    def __init__(self):
        self.inbox = []
        self.outbox = []
        self.ops = 0

    def enqueue(self, x):
        self.inbox.append(x)
        self.ops += 1
        print("enqueue", x, "-> inbox:", self.inbox)

    def _transfer(self):
        while self.inbox:
            self.outbox.append(self.inbox.pop())
            self.ops += 2  # one pop + one push
        print("  TRANSFER: outbox now", self.outbox)

    def dequeue(self):
        if not self.outbox:
            self._transfer()
        x = self.outbox.pop()
        self.ops += 1
        print("dequeue ->", x, "| inbox:", self.inbox, "outbox:", self.outbox)
        return x

