class ResizingTable:
    def __init__(self):
        self.cap = 4
        self.buckets = [[] for _ in range(self.cap)]
        self.size = 0

    def _rehash(self):
        old = [k for bucket in self.buckets for k in bucket]
        self.cap *= 2
        self.buckets = [[] for _ in range(self.cap)]
        for k in old:
            self.buckets[k % self.cap].append(k)
        print("  RESIZE to capacity", self.cap, "at size", self.size,
              "(load factor %.2f)" % (self.size / self.cap))

    def insert(self, k):
        self.buckets[k % self.cap].append(k)
        self.size += 1
        if self.size / self.cap > 0.75:
            self._rehash()

