        self.children = {}
        self.is_word = False

class Trie:
    def __init__(self):
        self.root = Node()
        self.nodes = 0

    def insert(self, word):
        node = self.root
        for ch in word:
            if ch not in node.children:
                node.children[ch] = Node()
                self.nodes += 1
            node = node.children[ch]
        node.is_word = True

    def _descend(self, prefix):
        node = self.root
        for ch in prefix:
            if ch not in node.children:
                return None
            node = node.children[ch]
        return node

    def words_with_prefix(self, prefix):
        node = self._descend(prefix)
        if node is None:
            return []
        results = []
        def walk(n, path):
            if n.is_word:
                results.append(path)
            for ch in sorted(n.children):
                walk(n.children[ch], path + ch)
        walk(node, prefix)
        return results

