class LFU:
    def __init__(self, cap):
        self.cap = cap
        self.values = {}
        self.counts = {}
        self.insertion = {}
        self.clock = 0

    def _show(self, action):
        state = {k: self.counts[k] for k in self.values}
        print(action, "| cache with counts:", state)

    def get(self, key):
        if key in self.values:
            self.counts[key] += 1
            self._show("get " + key + " HIT")
            return self.values[key]
        self._show("get " + key + " MISS")
        return None

    def put(self, key, value):
        if key not in self.values and len(self.values) >= self.cap:
            victim = min(self.values, key=lambda k: (self.counts[k], self.insertion[k]))
            print("  evicting", victim, "(count", str(self.counts[victim]) + ")")
            del self.values[victim], self.counts[victim], self.insertion[victim]
        self.values[key] = value
        self.counts[key] = self.counts.get(key, 0) + 1
        if key not in self.insertion:
            self.insertion[key] = self.clock
            self.clock += 1
        self._show("put " + key)

