def model_naive(workers=5):
    cache = {}
    backend_loads = 0
    results = []
    # all workers check before anyone fills: the classic race window
    checks = ["config" in cache for _ in range(workers)]
    for i in range(workers):
        if not checks[i]:
            backend_loads += 1
            cache["config"] = "v1"
        results.append(cache["config"])
    return backend_loads, results

def model_coalesced(workers=5):
    cache = {}
    backend_loads = 0
    results = []
    for i in range(workers):
        if "config" not in cache:
            backend_loads += 1
            cache["config"] = "v1"
            results.append(cache["config"] + " (loaded by worker " + str(i) + ")")
        else:
            results.append(cache["config"] + " (cache hit)")
    return backend_loads, results

loads_a, res_a = model_naive()
print("no coordination: backend loads =", loads_a, "| workers got:", res_a)
loads_b, res_b = model_coalesced()
