def naive_calls(n):
    # C(n) = C(n-1) + C(n-2) + 1, C(0) = C(1) = 1
    a, b = 1, 1
    for _ in range(2, n + 1):
        a, b = b, a + b + 1
    return b if n >= 1 else a

