        self.policy = policy
        self.data = OrderedDict()

    def get(self, key):
        if key in self.data:
            if self.policy == "LRU":
                self.data.move_to_end(key)
            print(self.policy, "get", key, "-> HIT | order:", list(self.data))
            return True
