def write_through(writes):
    store = {}
    cache = {}
    store_writes = 0
    for k, v in writes:
        cache[k] = v
        store[k] = v
        store_writes += 1
    return store_writes, store

def write_back(writes, cap=2):
    store = {}
    cache = {}   # key -> [value, dirty]
    order = []
    store_writes = 0
    def evict_oldest():
        nonlocal store_writes
        oldest = order.pop(0)
        val, dirty = cache.pop(oldest)
        if dirty:
            store[oldest] = val
            store_writes += 1
    for k, v in writes:
        if k not in cache:
            if len(cache) >= cap:
                evict_oldest()
            order.append(k)
        cache[k] = [v, True]
    while order:
        evict_oldest()
    return store_writes, store

