M = 32

def hashes(item):
    out = []
    for name in ("md5", "sha1", "sha256"):
        digest = hashlib.new(name, item.encode()).hexdigest()
        out.append(int(digest, 16) % M)
    return out

class Bloom:
    def __init__(self):
        self.bits = [0] * M

    def add(self, item):
        for pos in hashes(item):
            self.bits[pos] = 1

    def __contains__(self, item):
        return all(self.bits[pos] == 1 for pos in hashes(item))

