WINDOW = 5
window = deque()
in_window = set()

def process(event):
    if event in in_window:
        verdict = "SEEN-RECENTLY"
    else:
        verdict = "NEW"
    if event in in_window:
        window.remove(event)
    window.append(event)
    in_window.add(event)
    while len(window) > WINDOW:
        old = window.popleft()
