def trie_collect(prefix):
    global visits
    node = root
    for ch in prefix:
        visits += 1
        node = node.children[ch]
    out = []
    def walk(n, path):
        global visits
        visits += 1
        if n.is_word:
            out.append(path)
        for ch in sorted(n.children):
            walk(n.children[ch], path + ch)
    walk(node, prefix)
    return out

